import json,sys,os
d=sys.argv[1]
for line in open(os.path.join(d,'cc.stdout.jsonl'),errors='replace'):
    try: e=json.loads(line)
    except: continue
    t=e.get('type')
    if t=='result':
        print('RESULT:',json.dumps({k:e.get(k) for k in ['subtype','is_error','num_turns','duration_ms','result','total_cost_usd']},ensure_ascii=False)[:800])
    elif t=='assistant':
        blocks=e.get('message',{}).get('content',[])
        kinds=[b.get('type')+(':'+b.get('name','') if b.get('type')=='tool_use' else '') for b in blocks]
        print('ASSISTANT blocks',kinds)
        for b in blocks:
            if b.get('type')=='text': print('   text:',repr(b['text'])[:300])
            if b.get('type')=='tool_use': print('   tool:',json.dumps(b.get('input'),ensure_ascii=False)[:200])
    elif t=='user':
        blocks=e.get('message',{}).get('content',[])
        for b in blocks:
            if b.get('type')=='tool_result':
                print('TOOL_RESULT error=',b.get('is_error'),'content=',repr(b.get('content'))[:300])
print('--- stderr tail ---')
print(open(os.path.join(d,'cc.stderr.log'),errors='replace').read()[-600:])
PY
done

